#![cfg(feature = "storage")]
//! Real model output, synthetic public DE/EN text. Fixture generated by the
//! independent knowledge peer using canonical Qwen3-Embedding Q8_0 + llama.cpp
//! b12359 CPU, SHA pinned below. No model is loaded by this correctness test.
use loklm_core::{session::Sessions, store::Store};
use serde_json::Value;
use sha2::{Digest, Sha256};
#[test]
fn actual_qwen_vectors_retrieve_correct_original_sources_after_reopen() {
    let bytes = include_bytes!("fixtures/actual-qwen-vectors.json");
    assert_eq!(
        hex::encode(Sha256::digest(bytes)),
        "d1b1a60687c17003af977d7e18316766e22f8e87a441058f430cb51d725c01bb"
    );
    let fixture: Value = serde_json::from_slice(bytes).unwrap();
    let fingerprint = fixture["model_fingerprint"].as_str().unwrap();
    let root = tempfile::tempdir().unwrap();
    let path = root.path().join("meta.db");
    let sessions = Sessions::default();
    sessions.publish(sessions.epoch()).unwrap();
    let t = sessions.ticket().unwrap();
    let mut store = Store::open(&path, &[52; 32], true).unwrap();
    store.initialize_native_index(&t).unwrap();
    for row in fixture["rows"].as_array().unwrap() {
        let source = row["source"].as_str().unwrap();
        store
            .import_text(
                &format!("synthetic://{source}/{}.txt", row["id"]),
                source,
                row["text"].as_str().unwrap(),
                &t,
            )
            .unwrap();
        let pending = store.pending_vectors(fingerprint, 1, &t).unwrap();
        assert_eq!(pending.len(), 1);
        let vector: Vec<f32> = serde_json::from_value(row["vector"].clone()).unwrap();
        store
            .put_vector(pending[0].chunk_id, fingerprint, &vector, &t)
            .unwrap();
    }
    drop(store);
    let store = Store::open(&path, &[52; 32], false).unwrap();
    assert!(
        store
            .pending_vectors(fingerprint, 1, &t)
            .unwrap()
            .is_empty()
    );
    for query in fixture["queries"].as_array().unwrap() {
        let vector: Vec<f32> = serde_json::from_value(query["vector"].clone()).unwrap();
        let hits = store.dense(&vector, fingerprint, 5, &t).unwrap();
        assert_eq!(hits.len(), 5);
        let source = store.source(hits[0].chunk_id, &t).unwrap();
        assert_eq!(source.title, query["expected_source"], "{}", query["text"]);
        assert!(
            fixture["rows"]
                .as_array()
                .unwrap()
                .iter()
                .any(|r| r["source"] == source.title && r["text"] == source.text)
        );
    }
}
